import {SERVICE_STAGES,STAGE_CHANGES,GLOBAL_CHANGES} from './service-policy.js';
import {DATA,programFor,coursesFor,creditsOf,label} from './planner.js';
import {minorSummary} from './minor-summary.js';
import {planIssues} from './guidance.js';
import {questionnaireCard,questionNavigation} from './question-cards.js';
import {selectedMinor} from './minors.js';
import {dashboardCopy} from './dashboard-copy.js';
import {currentCourse} from './course-details.js';
import {courseGroups,courseSemester} from './course-groups.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const short=(s,n=130)=>{s=String(s||'').replace(/\s+/g,' ').trim();return s.length>n?s.slice(0,n-1).replace(/\s+\S*$/,'')+'…':s;};
const button=(action,text,primary=false,extra='')=>`<button type="button" class="button ${primary?'primary':'secondary'}" data-action="${action}" ${extra}>${text}</button>`;
const isBusy=runtime=>!!(runtime.dashboardBusy||runtime.busy);
const tabs=[['overview','Your space','◈'],['direction','Direction','↗'],['courses','Courses','▤'],['opportunities','Opportunities','◎'],['semesters','Semesters','▦']];
export function academicCombination(profile){
 const degree=programFor(profile),tracks=[...new Set([profile.track,profile.secondTrack].filter(Boolean))].map(id=>degree.tracks.find(t=>t.id===id)?.name).filter(Boolean),minor=selectedMinor(profile);
 return [...tracks,...(minor?[minor.name+' minor']:[])].join(' + ');
}
export function dashboardReady(j,plan){return {direction:!!(plan||j.programChosen&&j.advice?.kind==='recommend'),courses:!!(plan||j.details?.choices),opportunities:!!(plan?.targets?.internships?.length||plan?.targets?.exchanges?.length||j.details?.internships?.length||j.details?.exchanges?.length),semesters:!!plan};}
export function dashboardView(state,runtime={},account=null){
 const service=runtime.service,guide=!!(service&&!service.saved&&service.step<5),step=guide?SERVICE_STAGES[service.step]:null;
 if(runtime.serviceError)return `<section class="account-welcome"><h1>Let’s reconnect your workspace.</h1><p>${esc(runtime.serviceError)}</p>${button('dashboard-service-reload','Try again',true)}</section>`;
 const j=state.journey,plan=state.phase==='draft'?state.draftPlan:state.plan,profile=plan?.profile||j.profile,degree=programFor(profile),ready=dashboardReady(j,plan),panel=guide?step.panel:runtime.dashboardPanel||'overview',begun=!!(j.studentContext||j.advice||plan),name=account?.firstName||'',draft=state.phase==='draft';
 if(!begun||runtime.dashboardWelcome&&!ready.direction)return `<section class="launch-space" aria-busy="${isBusy(runtime)}"><span class="dashboard-kicker">YOUR NEXT CHAPTER</span><h1>${name?`Hi ${esc(name)}.<br>`:''}Let’s find your path.</h1><p>A few taps. A plan that feels like you.</p><dl class="service-included" aria-label="Your one-time GoPlan allowance"><div><dt>Roadmap</dt><dd>1</dd></div><div><dt>Guided AI changes</dt><dd>${SERVICE_STAGES.length*STAGE_CHANGES}</dd></div><div><dt>Global AI changes</dt><dd>${GLOBAL_CHANGES}</dd></div></dl><p class="service-included-note">Two changes per stage. Five more after saving.</p><div class="launch-path" aria-hidden="true"><span>✦</span><i></i><span>↗</span><i></i><span>◎</span><i></i><span>▦</span></div><fieldset class="dashboard-content" ${isBusy(runtime)?'disabled':''}>${button('dashboard-start','Let’s go →',true)}</fieldset>${working(runtime)}<span class="launch-note">For students starting their first semester at AUI.</span></section>`;
 if(state.phase==='journey'&&!ready.direction&&j.advice?.kind==='clarify'){
  const remaining=service?.stageChanges?.[0]??2;
  return `<section class="discovery-space" aria-busy="${isBusy(runtime)}"><span class="dashboard-kicker">ONE QUICK FOLLOW-UP</span><fieldset class="dashboard-content" ${isBusy(runtime)?'disabled':''}>${remaining>0?`<form id="dashboard-clarification-form" class="discovery-card"><h2>${esc(short(j.advice.questions?.[0]||j.advice.summary,200))}</h2><label class="field">Your answer<textarea name="answer" rows="3" maxlength="2500" required ${isBusy(runtime)?'disabled':''}>${esc(j.answers||'')}</textarea></label><button class="button primary" type="submit" ${isBusy(runtime)?'disabled':''}>Find my direction →</button><p class="small-note">Uses one of your ${remaining} remaining Direction changes.</p></form>`:`<div class="discovery-card"><h2>Choose the direction that feels right.</h2><p>Your two Direction changes are used. Choose your degree to continue.</p></div>`}<div class="deck-actions">${button('dashboard-direction-options','Choose my degree myself',remaining===0)}</div></fieldset>${working(runtime)}${failure(runtime)}</section>`;
 }
 if(state.phase==='journey'&&!ready.direction)return `<section class="discovery-space" aria-busy="${isBusy(runtime)}"><div class="discovery-top"><button class="text-button" data-action="dashboard-home" ${isBusy(runtime)?'disabled':''}>← Your space</button><span class="dashboard-kicker">FIND YOUR SPARK</span></div><fieldset class="dashboard-content" ${isBusy(runtime)?'disabled':''}><div class="discovery-card">${questionnaireCard(j,runtime.validation)}</div><div class="discovery-actions">${isBusy(runtime)?'':questionNavigation(j)}</div></fieldset>${working(runtime)}${failure(runtime)}</section>`;
 const section=dashboardCopy(panel,courseGroups(plan?.courses||coursesFor(profile),profile).find(g=>g.id===runtime.courseGroup)?.title,guide?step.target:runtime.targetGroup);
 const completed=Object.values(ready).filter(Boolean).length,done=plan?plan.courses.filter(c=>plan.tracking?.[c.id]?.status==='completed'||plan.profile.priorCodes.includes(c.code)):[],doneCredits=creditsOf(done),totalCredits=plan?creditsOf(plan.courses):0;
 const rail=guide?`<div class="service-progress" aria-label="Stage ${service.step+1} of 5">${SERVICE_STAGES.map((def,i)=>`<span class="${i===service.step?'active':i<service.step?'done':''}"><b>${i<service.step?'✓':i+1}</b>${def.title}</span>`).join('')}</div>`:`<nav class="dashboard-tabs" aria-label="Your planning space">${tabs.map(([id,title,icon])=>`<button type="button" data-action="dashboard-panel" data-panel="${id}" class="${panel===id?'active':''}" ${panel===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${title}${ready[id]?'<i aria-label="Ready">✓</i>':''}</button>`).join('')}</nav>`;
 const heading=guide?`<header class="dashboard-heading"><div><span class="dashboard-kicker">${service.step+1} OF 5</span><h1>${step.title}</h1></div><span class="service-allowance" role="status">${service.stageChanges[service.step]} of ${STAGE_CHANGES} AI changes left</span></header>`:`<header class="dashboard-heading"><div><span class="dashboard-kicker">YOUR AUI PATH</span><h1>${panel==='overview'?(name?`${esc(name)}’s next chapter`:'Your next chapter'):esc(tabs.find(t=>t[0]===panel)?.[1]||'Your space')}</h1><button type="button" class="degree-chip" data-action="dashboard-direction-options" aria-label="Change your degree" ${isBusy(runtime)?'disabled':''}>${esc(profile.program)} <span aria-hidden="true">✎</span></button></div><div class="dashboard-actions">${service?.saved?`<button type="button" class="service-allowance" data-action="dashboard-panel" data-panel="overview" aria-label="${service.globalRemaining} of ${GLOBAL_CHANGES} global AI changes left. Open Your space.">${service.globalRemaining} of ${GLOBAL_CHANGES} global AI changes left</button>`:''}${draft?button('dashboard-save','Save this plan',true):!service?.saved?button('dashboard-build','Build my roadmap →',true):''}</div></header>`;
 let body='';
 if(panel==='direction')body=directionCard(profile,j,plan,true);
 else if(panel==='courses')body=courseDeck(profile,j,plan,runtime);
 else if(panel==='opportunities')body=opportunityDeck(j,plan,guide?{...runtime,targetGroup:step.target}:runtime);
 else if(panel==='semesters')body=semesterDeck(profile,j,plan,runtime);
 else body=`<section class="path-hero"><div><span class="dashboard-kicker">${plan&&!draft?'YOUR DEGREE':'A DIRECTION TO EXPLORE'}</span><h2>${esc(degree.name.replace(/^Bachelor of (Science|Arts) in /,'').replace(/^Bachelor of /,''))}</h2><p>${esc(academicCombination(profile))}</p><button class="text-button" data-action="dashboard-panel" data-panel="direction">Edit degree choices ↗</button></div><div class="path-orbit" aria-hidden="true"><span>YOU</span><b>✦</b></div></section>${plan&&!draft?`<div class="degree-progress"><div><span>${doneCredits} / ${totalCredits} credits completed</span><button type="button" class="text-button" data-action="dashboard-panel" data-panel="semesters">Update progress ↗</button></div><progress value="${doneCredits}" max="${totalCredits||1}" aria-label="Degree credits completed"></progress></div>`:''}<section class="path-grid">${tile('courses','Your courses',ready.courses?`${courseGroups(plan?.courses||coursesFor(profile),profile).length} course groups`:'Turn your interests into skills',ready.courses?(plan?'Edit courses':'Explore courses'):'Choose my courses','▤')}${tile('opportunities','Beyond the classroom',ready.opportunities?`${(plan?.targets?.internships||j.details?.internships||[]).length} companies · ${(plan?.targets?.exchanges||j.details?.exchanges||[]).length} exchange ideas`:'Find your people and places',ready.opportunities?'Explore matches':'Find my opportunities','◎')}${tile('semesters','Your semester plan',plan?`${plan.terms.filter(t=>!['prior','pending'].includes(t.id)).length} semesters mapped`:'A clear path from here to graduation',plan?'Edit my plan':'Map my semesters','▦')}</section>${plan?`<div class="dashboard-footnote">${draft?'<span>Preview · save when it feels right</span>':''}${button('dashboard-export','Export Excel')}${button('mistake-report','Report a mistake')}</div>`:''}`;
 if(guide||service?.saved)body=body.replace(/<button[^>]*data-action="dashboard-change"[^>]*>[\s\S]*?<\/button>/g,'');
 if(guide)body=body.replace(/<button[^>]*data-action="dashboard-build"[^>]*>[\s\S]*?<\/button>/g,'');
 if(guide)body=body.replace(/<div class="deck-filters"[^>]*>[\s\S]*?<\/div>/g,'');
 return `<section class="student-dashboard" aria-busy="${isBusy(runtime)}">${heading}${rail}${working(runtime)}${failure(runtime)}${draft&&plan?.degreeAllocationChanges?.length?`<p class="dashboard-notice">${esc(plan.degreeAllocationChanges.map(c=>c.courseCode).join(', '))} now uses an existing free elective. Review and save your updated plan.</p>`:''}${draft&&plan?.revisionAssessment?.delayed?`<p class="dashboard-error" role="status">This change moves graduation from ${esc(plan.revisionAssessment.before)} to ${esc(plan.revisionAssessment.after)}.</p>`:''}${plan?.revisionAssessment?.unmatchedRecords?`<p class="dashboard-notice">${plan.revisionAssessment.unmatchedRecords} past course${plan.revisionAssessment.unmatchedRecords===1?' needs':'s need'} adviser review for credit in this degree. Your study record is kept.</p>`:''}<fieldset class="dashboard-content" ${isBusy(runtime)?'disabled':''}>${body}</fieldset>${runtime.dashboardNotice?`<p class="dashboard-notice" role="status">${esc(short(runtime.dashboardNotice,170))}</p>`:''}${serviceCommand(runtime,guide,section,panel)}${guide?`<div class="service-next">${button('dashboard-stage-next',service.step===4?'Review my plan →':'Continue to '+SERVICE_STAGES[service.step+1].title+' →',true,isBusy(runtime)?'disabled':'')}</div>`:''}</section>`;
}
function tile(panel,title,subtitle,cta,icon){return `<article class="path-tile"><span class="path-tile-icon" aria-hidden="true">${icon}</span><h2>${title}</h2><p>${esc(subtitle)}</p>${button('dashboard-open',cta,false,`data-panel="${panel}"`)}</article>`;}
function working(runtime){return isBusy(runtime)?`<div class="dashboard-working" role="status"><span class="working-spinner" aria-hidden="true"></span><div><strong>${esc(runtime.dashboardWork||'Shaping your path…')}</strong><small>You can stay right here.</small></div></div>`:'';}
function failure(runtime){
 if(!runtime.aiError)return '';
 const s=runtime.service,remaining=s?(s.saved?s.globalRemaining:s.step<5?s.stageChanges[s.step]:0):1;
 const recovery=runtime.aiFailure?.retryable===false?(s&&!s.saved&&s.step===0?button('dashboard-direction-options','Choose my degree'):remaining>0?button('dashboard-change','Try a different request'):''):button('dashboard-retry','Try again');
 return `<div class="dashboard-error" role="alert"><p>${esc(short(runtime.aiError,180))}</p>${recovery}</div>`;
}
function directionCard(profile,j,plan,full=false){
 const degree=programFor(profile),a=plan?.decisions?.advice?.academic||j.advice?.academic||{},minor=selectedMinor(profile),items=[['Degree',degree.name,a.rationale],['Focus',degree.tracks.find(t=>t.id===profile.track)?.name||'A broad foundation',a.focusRationale],...(profile.secondTrack?[['Second focus',degree.tracks.find(t=>t.id===profile.secondTrack)?.name,a.secondFocusRationale]]:[]),...(minor?[['Minor',minor.name,a.minorRationale]]:[])];
 return `<section class="decision-deck">${items.map(([kind,name,reason])=>`<article class="decision-card"><span class="dashboard-kicker">${kind}</span><h2>${esc(name)}</h2>${reason?`<button class="text-button" data-action="dashboard-why" data-kind="${kind}">Why this match? ↗</button>`:''}</article>`).join('')}</section><div class="deck-actions">${button('dashboard-change','Try a different combination')}${button('dashboard-direction-options','Choose the details myself')}</div>`;
}
function courseDeck(profile,j,plan,runtime){
 if(!dashboardReady(j,plan).courses)return emptyDeck('Skills for your next chapter','Let GoPlan pick courses that fit your direction.','dashboard-courses','Choose my courses →');
 const all=plan?.courses||coursesFor(profile),groups=courseGroups(all,profile),selected=groups.find(g=>g.id===runtime.courseGroup)||groups[0],minor=minorSummary(profile),visible=[...(selected?.courses||[])].sort((a,b)=>courseSemester(plan,a).order-courseSemester(plan,b).order),minorGroup=selected?.id==='minor';
 return `<div class="deck-heading"><div><h2>${esc(minorGroup?(selectedMinor(profile)?.name?selectedMinor(profile).name+' minor':'Your minor courses'):selected?.heading||'Your courses')}</h2><p>${visible.length} courses · ${selected?.credits||0} credits${minorGroup&&minor?.approvalRequired?' · adviser confirmation':''}</p></div>${button('dashboard-change','Ask GoPlan to change a course')}</div><div class="deck-filters course-group-filters" role="group" aria-label="Degree requirements">${groups.map(g=>`<button type="button" class="${selected?.id===g.id?'active':''}" data-action="dashboard-course-group" data-group="${g.id}" aria-pressed="${selected?.id===g.id}">${esc(g.title)} <span>${g.courses.length}</span></button>`).join('')}</div><div class="course-group-context"><p>${esc(selected?.description||'')}${plan?'':' Semester timing appears when you build your roadmap.'}</p>${plan?'<button type="button" class="text-button" data-action="dashboard-panel" data-panel="semesters">See semester map ↗</button>':button('dashboard-build','Map my semesters →')}</div>${plan?'<p class="manual-edit-hint">Select a course to move it, swap an elective or update progress. No AI changes used.</p>':''}<div class="course-deck">${visible.map(c=>courseCard(c,profile,plan,true)).join('')}</div>`;

}
function opportunityDeck(j,plan,runtime){
 const type=runtime.targetGroup||'internships',targets=plan?.targets||j.details||{},items=targets[type]||[];
 if(!items.length){
  const exchanges=type==='exchanges';
  if(runtime.service?.saved||runtime.service&&runtime.service.step>=5)return `${opportunityFilters(type)}<section class="empty-deck"><h2>${exchanges?'No exchange destinations saved':'No internship targets saved'}</h2><p>Your courses and semester plan are ready to edit.</p>${button('dashboard-panel','Open my semester plan',false,'data-panel="semesters"')}</section>`;
  return emptyDeck(exchanges?'Find your exchange destinations':'Find your internship targets',exchanges?'Places to study abroad, matched to your interests.':'Moroccan internship targets, matched to your interests.','dashboard-targets',exchanges?'Find my exchange destinations →':'Find my internship targets →');
 }
 return `<div class="deck-heading"><div><h2>${type==='internships'?'Moroccan Internship Targets':'Exchange destinations'}</h2><p>Targets to explore. Openings and eligibility still need checking.</p></div>${button('dashboard-change','Different matches')}</div>${opportunityFilters(type)}<div class="opportunity-deck">${items.map((t,i)=>`<article class="opportunity-flashcard"><span class="dashboard-kicker">${esc(type==='exchanges'?t.country||'Exchange':t.organizationType==='startup'?'Startup':'Morocco')}</span><h3>${esc(t.name)}</h3><button class="text-button" data-action="dashboard-target" data-target-type="${type}" data-target-index="${i}">Explore this match ↗</button></article>`).join('')||'<p>No suitable match yet. Ask GoPlan to explore another focus.</p>'}</div>`;
}
function opportunityFilters(type){return `<div class="deck-filters" role="group" aria-label="Opportunity type">${[['internships','Moroccan Internship Targets'],['exchanges','Exchange destinations']].map(([id,title])=>`<button type="button" class="${type===id?'active':''}" data-action="dashboard-target-group" data-group="${id}" aria-pressed="${type===id}">${title}</button>`).join('')}</div>`;}
function semesterDeck(profile,j,plan,runtime){
 if(!plan)return emptyDeck('Your future, one semester at a time','We’ll connect your choices into a course sequence.','dashboard-build','Map my semesters →');
 const terms=plan.terms.filter(t=>t.id!=='prior'),selected=terms.find(t=>t.id===runtime.selectedTerm)||terms.find(t=>t.id!=='pending'&&t.courses.some(id=>plan.tracking?.[id]?.status==='in-progress'))||terms.find(t=>t.id!=='pending'&&t.courses.some(id=>plan.tracking?.[id]?.status!=='completed'))||terms[0],review=plan.revisionAssessment;
 return `<div class="deck-heading"><div><h2>Your semester map</h2><p>${profile.regularCourses} courses per regular term${profile.summers?` · ${profile.summerCourses} per summer`:' · summers free'}</p></div>${button('dashboard-pace','Change my pace')}</div>${languageCenterControl(profile,runtime)}<p class="manual-edit-hint">Select a course to change its semester or progress. No AI changes used.</p><div class="semester-pills" aria-label="Choose a semester">${terms.map(t=>`<button class="${selected?.id===t.id?'active':''}" data-action="dashboard-term" data-term="${esc(t.id)}">${esc(label(t))}${t.lc?' · Language Center':''}</button>`).join('')}<button type="button" class="semester-add" data-action="dashboard-add-term" ${isBusy(runtime)?'disabled':''}>+ Add semester</button></div><div class="semester-focus"><div class="deck-heading"><h3>${esc(selected?label(selected):'Your courses')}${selected?.lc?' · Language Center':''}</h3>${selected?.lc?'':`<span>${creditsOf((selected?.courses||[]).map(id=>plan.courses.find(c=>c.id===id)))} credits</span>`}</div>${selected?.lc?'<p class="language-center-note">Time reserved for Language Center. Your degree courses follow.</p>':''}<div class="course-deck">${(selected?.courses||[]).map(id=>courseCard(plan.courses.find(c=>c.id===id),profile,plan,false)).join('')||(selected?.lc?'':'<p>Space for your next chapter.</p>')}</div></div>`;
}
function languageCenterControl(profile,runtime){
 return `<form id="dashboard-language-center-form" class="language-center-control"><div><label for="language-center-semesters">Language Center</label><p id="language-center-help">Reserve semesters before your degree courses begin.</p></div><div class="language-center-actions"><select id="language-center-semesters" name="lc" aria-describedby="language-center-help" ${isBusy(runtime)?'disabled':''}>${[[0,'No Language Center'],[1,'1 semester'],[2,'2 semesters']].map(([value,text])=>`<option value="${value}" ${profile.lc===value?'selected':''}>${text}</option>`).join('')}</select><button type="submit" class="button secondary" ${isBusy(runtime)?'disabled':''}>Update map</button></div><p id="dashboard-language-center-error" class="field-error" role="alert"></p></form>`;
}
function emptyDeck(title,copy,action,cta){return `<section class="empty-deck"><span aria-hidden="true">✦</span><h2>${title}</h2><p>${copy}</p>${button(action,cta,true)}</section>`;}

function courseStatus(plan,c){const status=plan?.tracking?.[c.id]?.status;return status==='completed'||plan?.profile?.priorCodes?.includes(c.code)?'✓ Completed':status==='in-progress'?'● Taking now':status==='retake'?'Retake':'';}

function courseCard(c,profile,plan,showSemester){
 c=currentCourse(c,profile);
 const status=courseStatus(plan,c),role=courseGroups([c],profile)[0]?.title||c.category||'Degree requirement',semester=courseSemester(plan,c);
 return `<button type="button" class="course-flashcard" data-action="dashboard-course" data-course-id="${esc(c.id)}" aria-label="${esc((plan?'Edit ':'View ')+c.title+(status?' · '+status:''))}"><span class="course-card-top"><span class="course-flash-type">${esc(role)}</span>${status?`<span class="course-progress-status">${esc(status)}</span>`:''}</span><h3>${esc(c.title)}</h3><span class="course-code">${esc(c.code||'Course to confirm')} <b>${c.credits} cr</b></span>${showSemester&&plan?`<span class="course-semester ${semester.termId==='pending'?'unplaced':''}">${esc(semester.text)}</span>`:''}</button>`;
}

function serviceCommand(runtime,guide,copy,panel){
 const service=runtime.service;if(service&&!guide&&!service.saved)return '<p class="service-finished">Save your plan to unlock five global AI changes.</p>';if(service?.saved&&panel!=='overview')return '';
 const remaining=guide?service.stageChanges[service.step]:service?.globalRemaining,disabled=isBusy(runtime)||remaining===0;
 if(remaining===0)return `<div class="service-finished">${guide?'Your two changes for this stage are used. Continue when ready.':'Your five global AI changes are used. You can still edit your plan manually or export it to Excel.'}</div>`;
 return `<form id="dashboard-command-form" class="dashboard-command"><label for="dashboard-request">${guide?esc(copy.label):'What would you like to change in your plan?'}</label><div><input id="dashboard-request" name="request" maxlength="2500" required minlength="5" placeholder="${esc(guide?copy.placeholder:'Describe the change you want GoPlan to make.')}" value="${esc(runtime.dashboardPrefill||'')}" ${disabled?'disabled':''}><button type="submit" class="button primary" ${disabled?'disabled':''}>${isBusy(runtime)?'Updating your plan…':'Ask GoPlan ↗'}</button></div></form>`;
}
